<?php
require_once dirname(__DIR__).'/includes/functions.php';$admin=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT * FROM events WHERE id=? AND deleted_at IS NULL');$s->execute([$id]);$event=$s->fetch();if($event){db()->prepare("UPDATE events SET status='Cancelled',deleted_at=NOW() WHERE id=?")->execute([$id]);notify_event_students($id,'cancel','Event cancelled','The event “'.$event['title'].'” has been cancelled by the organizers.');flash('success','Event cancelled. Registered students were notified.');}redirect('admin/events.php');}
$q=trim((string)($_GET['q']??''));$category=(string)($_GET['category']??'');$status=(string)($_GET['status']??'');$date=(string)($_GET['date']??'');$page=max(1,(int)($_GET['page']??1));$limit=10;$where=['deleted_at IS NULL'];$params=[];if($q!==''){$where[]='(title LIKE ? OR venue LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if($category!==''){$where[]='category=?';$params[]=$category;}if(in_array($status,['Open','Closed','Cancelled'],true)){$where[]='status=?';$params[]=$status;}if(valid_iso_date($date)){$where[]='event_date=?';$params[]=$date;}$clause=implode(' AND ',$where);$count=db()->prepare("SELECT COUNT(*) FROM events WHERE $clause");$count->execute($params);$total=(int)$count->fetchColumn();$s=db()->prepare("SELECT * FROM events WHERE $clause ORDER BY event_date DESC LIMIT $limit OFFSET ".(($page-1)*$limit));$s->execute($params);$events=$s->fetchAll();$cats=db()->query('SELECT DISTINCT category FROM events ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Manage events';require dirname(__DIR__).'/includes/header.php';
?>
<div class="d-flex justify-content-between align-items-end mb-4"><div><p class="text-primary text-uppercase small fw-bold mb-1">Admin workspace</p><h1 class="h2 fw-bold">Manage events</h1></div><a class="btn btn-primary" href="<?=e(url('admin/event_form.php'))?>"><i class="bi bi-plus-lg"></i> New event</a></div>
<form class="card p-3 mb-3 row g-2 flex-row"><div class="col-md"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search title or venue"></div><div class="col-md-3"><select class="form-select" name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option <?= $category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="date" name="date" value="<?=e($date)?>" aria-label="Event date"></div><div class="col-md-2"><select class="form-select" name="status"><option value="">Any status</option><?php foreach(['Open','Closed','Cancelled'] as $st):?><option <?= $status===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-outline-primary">Filter</button></div></form>
<div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Event</th><th>Date / venue</th><th>Registrations</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach($events as $event):$s=db()->prepare("SELECT COUNT(*) FROM registrations WHERE event_id=? AND status<>'Cancelled'");$s->execute([$event['id']]);$num=(int)$s->fetchColumn();?><tr><td><strong><?=e($event['title'])?></strong><div class="small text-secondary"><?=e($event['category'])?></div></td><td><?=e(date('M j, Y',strtotime($event['event_date'])))?><div class="small text-secondary"><?=e($event['venue'])?></div></td><td><?=$num?> / <?=e((string)$event['max_participants'])?><div class="progress" style="height:5px"><div class="progress-bar" style="width:<?=min(100,(int)round($num/max(1,(int)$event['max_participants'])*100))?>%"></div></div></td><td><span class="badge <?=$event['status']==='Open'?'text-bg-success':($event['status']==='Cancelled'?'text-bg-danger':'text-bg-secondary')?>"><?=e($event['status'])?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="<?=e(url('admin/event_form.php?id='.(int)$event['id']))?>">Edit</a> <a class="btn btn-sm btn-outline-secondary" href="<?=e(url('admin/participants.php?event='.(int)$event['id']))?>">Participants</a><form class="d-inline" method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$event['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Cancel this event and notify all registered students?">Cancel</button></form></td></tr><?php endforeach;?><?php if(!$events):?><tr><td colspan="5" class="empty-state">No events found.</td></tr><?php endif;?></tbody></table></div>
<?php if($total>$limit):?><nav class="mt-3"><ul class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++):?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="?<?=http_build_query(['q'=>$q,'category'=>$category,'date'=>$date,'status'=>$status,'page'=>$i])?>"><?=$i?></a></li><?php endfor;?></ul></nav><?php endif;?>
